query BatchedDashboardQuery($c0_zoneTag: string) {
  viewer {
    scope_0: zones(filter: {zoneTag: $c0_zoneTag}) {
      c0_total: httpRequestsAdaptiveGroups(filter: $c0_filter, limit: 1) {
        count
        sum {
          edgeResponseBytes
          visits
        }
        avg {
          sampleInterval
        }
      }
      c0_sparkline: httpRequestsAdaptiveGroups(filter: $c0_filter, limit: 5000, orderBy: [date_ASC]) {
        count
        dimensions {
          ts: date
        }
        sum {
          edgeResponseBytes
          visits
        }
      }
      c3_numerator: httpRequestsAdaptiveGroups(filter: $c3_numeratorFilter, limit: 1) {
        count
      }
      c3_sparklineNumerator: httpRequestsAdaptiveGroups(filter: $c3_numeratorFilter, limit: 5000, orderBy: [date_ASC]) {
        count
        dimensions {
          ts: date
        }
      }
      c4_numerator: httpRequestsAdaptiveGroups(filter: $c4_numeratorFilter, limit: 1) {
        count
      }
      c4_sparklineNumerator: httpRequestsAdaptiveGroups(filter: $c4_numeratorFilter, limit: 5000, orderBy: [date_ASC]) {
        count
        dimensions {
          ts: date
        }
      }
      c7_ts_series_0: httpRequestsAdaptiveGroups(limit: 5000, filter: $c7_ts_series_filter_0, orderBy: [date_ASC]) {
        count
        dimensions {
          ts: date
        }
      }
      c7_ts_series_0_total: httpRequestsAdaptiveGroups(limit: 1, filter: $c7_ts_series_filter_0) {
        count
      }
      c7_ts_series_1: httpRequestsAdaptiveGroups(limit: 5000, filter: $c7_ts_series_filter_1, orderBy: [date_ASC]) {
        count
        dimensions {
          ts: date
        }
      }
      c7_ts_series_1_total: httpRequestsAdaptiveGroups(limit: 1, filter: $c7_ts_series_filter_1) {
        count
      }
      c7_ts_series_2: httpRequestsAdaptiveGroups(limit: 5000, filter: $c7_ts_series_filter_2, orderBy: [date_ASC]) {
        count
        dimensions {
          ts: date
        }
      }
      c7_ts_series_2_total: httpRequestsAdaptiveGroups(limit: 1, filter: $c7_ts_series_filter_2) {
        count
      }
      c8_topN: httpRequestsAdaptiveGroups(filter: $c8_filter, limit: 5, orderBy: [count_DESC]) {
        count
        dimensions {
          metric_0: cacheStatus
        }
      }
      c9_topN: httpRequestsAdaptiveGroups(filter: $c9_filter, limit: $c9_limit, orderBy: [count_DESC]) {
        count
        dimensions {
          metric_0: clientRequestPath
        }
      }
    }
  }
}
